--###############
--## MONITORS ###
--###############

-- See https://wiki.hyprland.org/Configuring/Monitors/
-- monitor=,preferred,auto,auto

-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

hl.monitor({
	output = "eDP-1",
	mode = "1920x1080@60",
	position = "0x0",
	scale = "1",
})

--##################
--## MY PROGRAMS ###
--##################

-- See https://wiki.hyprland.org/Configuring/Keywords/

-- Set programs that you use
local terminal = "ghostty"
local discord = "discord"
local tmux = terminal .. " -e tmux"
local fileManager = "thunar"
local menu = "rofi -show drun -show-icons"
local browser = "firefox"
local toggleMonitor = "sh ~/.config/hypr/monitor_toggle.sh"
local displayMode = "sh ~/.config/hypr/display-mode.sh"
local onLidClosed = "sh ~/.config/hypr/lid_closed.sh"
local onLidOpened = "sh ~/.config/hypr/lid_opened.sh"

--################
--## AUTOSTART ###
--################

-- Autostart necessary processes (like notifications daemons, status bars, etc.)
-- Or execute your favorite apps at launch like this:

-- Favorite apps

-- env = XDG_CURRENT_DESKTOP,GNOME

-- Find coretemp hwmon path

-- Remote touchpad server
-- exec-once = sleep 5 && pkexec ~/scripts/remote-touchpad -scroll-speed 0.1 -secret helobang -bind :40001 -update-rate 60

--############################
--## ENVIRONMENT VARIABLES ###
--############################

-- See https://wiki.hyprland.org/Configuring/Environment-variables/

hl.env("XCURSOR_SIZE", "30")
hl.env("HYPRCURSOR_SIZE", "30")
hl.env("GTK_THEME", "Nordic")
hl.env("GTK2_RC_FILES", "/usr/share/themes/Nordic/gtk-2.0/gtkrc")
hl.env("QT_STYLE_OVERRIDE", "Nordic")
hl.env("HYPRSHOT_DIR", "$HOME/Pictures/Screenshots")

