-- Refer to https://wiki.hyprland.org/Configuring/Variables/

-- https://wiki.hyprland.org/Configuring/Variables/#general

hl.curve("easeOutQuint", { type = "bezier", points = { { 0.23, 1 }, { 0.32, 1 } } })
hl.curve("easeInOutCubic", { type = "bezier", points = { { 0.65, 0.05 }, { 0.36, 1 } } })
hl.curve("linear", { type = "bezier", points = { { 0, 0 }, { 1, 1 } } })
hl.curve("almostLinear", { type = "bezier", points = { { 0.5, 0.5 }, { 0.75, 1.0 } } })
hl.curve("quick", { type = "bezier", points = { { 0.15, 0 }, { 0.1, 1 } } })
hl.animation({
	leaf = "global",
	enabled = true,
	speed = 1,
	bezier = "default",
})
hl.animation({
	leaf = "border",
	enabled = true,
	speed = 1,
	bezier = "easeOutQuint",
})
hl.animation({
	leaf = "windows",
	enabled = true,
	speed = 1,
	bezier = "easeOutQuint",
})
hl.animation({
	leaf = "windowsIn",
	enabled = true,
	speed = 1,
	bezier = "easeOutQuint",
	style = "popin 87%",
})
hl.animation({
	leaf = "windowsOut",
	enabled = true,
	speed = 1,
	bezier = "linear",
	style = "popin 87%",
})
hl.animation({
	leaf = "fadeIn",
	enabled = true,
	speed = 0.1,
	bezier = "almostLinear",
})
hl.animation({
	leaf = "fadeOut",
	enabled = true,
	speed = 0.1,
	bezier = "almostLinear",
})
hl.animation({
	leaf = "fade",
	enabled = true,
	speed = 0.1,
	bezier = "quick",
})
hl.animation({
	leaf = "layers",
	enabled = true,
	speed = 1,
	bezier = "easeOutQuint",
})
hl.animation({
	leaf = "layersIn",
	enabled = true,
	speed = 1,
	bezier = "easeOutQuint",
	style = "fade",
})
hl.animation({
	leaf = "layersOut",
	enabled = true,
	speed = 1,
	bezier = "linear",
	style = "fade",
})
hl.animation({
	leaf = "fadeLayersIn",
	enabled = true,
	speed = 1,
	bezier = "almostLinear",
})
hl.animation({
	leaf = "fadeLayersOut",
	enabled = true,
	speed = 1,
	bezier = "almostLinear",
})
hl.animation({
	leaf = "workspaces",
	enabled = true,
	speed = 1,
	bezier = "almostLinear",
	style = "fade",
})
hl.animation({
	leaf = "workspacesIn",
	enabled = false,
	speed = 1,
	bezier = "almostLinear",
	style = "fade",
})
hl.animation({
	leaf = "workspacesOut",
	enabled = false,
	speed = 1,
	bezier = "almostLinear",
	style = "fade",
})

hl.device({
	name = "epic-mouse-v1",
	sensitivity = -0.5,
})

local mainMod = "CTRL + ALT"

hl.bind(mainMod .. " + Q", hl.dsp.exec_cmd(tmux))
hl.bind(mainMod .. " + X", hl.dsp.window.close())
hl.bind(mainMod .. " + M", hl.dsp.exit())
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd(fileManager))
hl.bind(mainMod .. " + B", hl.dsp.exec_cmd(browser))
hl.bind(mainMod .. " + I", hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + SHIFT + P", hl.dsp.window.pin())
hl.bind(mainMod .. " + SPACE", hl.dsp.exec_cmd(menu))
hl.bind(mainMod .. " + P", hl.dsp.window.pseudo())
hl.bind(mainMod .. " + O", hl.dsp.layout("togglesplit"))
hl.bind(mainMod .. " + code:119", hl.dsp.exec_cmd("hyprlock"))
hl.bind(mainMod .. " + C", hl.dsp.exec_cmd("hyprpicker -a"))
hl.bind(mainMod .. " + grave", hl.dsp.exec_cmd("/home/d/.local/bin/handy --toggle-transcription"))
hl.bind(
	mainMod .. " + V",
	hl.dsp.exec_cmd("rofi -modi clipboard:~/.config/cliphist/rofi-images -show clipboard -show-icons")
)
hl.bind(mainMod .. " + code:47", hl.dsp.exec_cmd("rofimoji --action copy"))
hl.bind(mainMod .. " + code:51", hl.dsp.exec_cmd("hyprctl reload"))
hl.bind(mainMod .. " + code:35", hl.dsp.exec_cmd(toggleMonitor))
hl.bind(mainMod .. " + code:34", hl.dsp.exec_cmd(displayMode))

hl.bind(mainMod .. " + h", hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + l", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + k", hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + j", hl.dsp.focus({ direction = "down" }))
hl.bind(mainMod .. " + u", hl.dsp.window.fullscreen({ mode = "maximized", action = "toggle" }))
hl.bind(mainMod .. " + y", hl.dsp.window.fullscreen({ mode = "fullscreen", action = "toggle" }))

hl.bind("SUPER + h", hl.dsp.window.resize({ x = 20, y = 0, relative = true }))
hl.bind("SUPER + l", hl.dsp.window.resize({ x = -20, y = 0, relative = true }))
hl.bind("SUPER + k", hl.dsp.window.resize({ x = 0, y = -20, relative = true }))
hl.bind("SUPER + j", hl.dsp.window.resize({ x = 0, y = 20, relative = true }))

hl.bind(mainMod .. " + left", hl.dsp.window.swap({ direction = "l" }))
hl.bind(mainMod .. " + right", hl.dsp.window.swap({ direction = "r" }))
hl.bind(mainMod .. " + up", hl.dsp.window.swap({ direction = "u" }))
hl.bind(mainMod .. " + down", hl.dsp.window.swap({ direction = "d" }))

hl.bind(mainMod .. " + 1", hl.dsp.focus({ workspace = 1 }))
