hl.window_rule({
	name = "recordly",
	match = {
		class = "^(Recordly)$",
	},
	float = true,
	center = true,
	border_size = 0,
})

hl.window_rule({
	name = "suppress-maximize-events",
	match = {
		class = ".*",
	},
	-- Ignore maximize requests from all apps. You'll probably like this.
	suppress_event = "maximize",
})

hl.window_rule({
	name = "fix-xwayland-drags",
	match = {
		class = "^$",
		title = "^$",
		xwayland = true,
		float = true,
		fullscreen = false,
		pin = false,
	},
	-- Fix some dragging issues with XWayland
	no_focus = true,
})

hl.window_rule({
	name = "fullscreen-all",
	match = {
		class = "com.mitchellh.ghostty",
	},
	fullscreen = true,
})

hl.window_rule({
	name = "waylyrics",
	match = {
		class = "io.github.waylyrics.Waylyrics",
	},
	float = true,
	pin = true,
	size = "100 100",
	move = "(monitor_w*0.82) 30",
	no_blur = true,
	no_shadow = true,
	border_size = 0,
})

