hl.on("hyprland.start", function()
	hl.exec_cmd("waybar")
	hl.exec_cmd("hyprpaper")
	hl.exec_cmd("muslimboard")
	hl.exec_cmd("hyprsunset")
	hl.exec_cmd("systemctl --user start hypridle")
	hl.exec_cmd("systemctl --user start hyprpolkitagent")
	hl.exec_cmd("systemctl --user start dunst")
	hl.exec_cmd("firefox")
	hl.exec_cmd(terminal, { workspace = "special:magic silent" })
	hl.exec_cmd(discord, { workspace = "10 silent" })
	hl.exec_cmd("wl-paste --watch cliphist store")
	hl.exec_cmd("kdeconnect-indicator")
	hl.exec_cmd('gsettings set org.gnome.desktop.interface color-scheme "prefer-dark"')
	hl.exec_cmd('gsettings set org.gnome.desktop.interface gtk-theme "Nordic"')
	hl.exec_cmd('gsettings set org.gnome.desktop.wm.preferences theme "Nordic"')
	hl.exec_cmd("XDG_CURRENT_DESKTOP=GNOME /usr/bin/gnome-keyring-daemon --start --components=pkcs11,secrets,ssh")

	hl.exec_cmd("sleep 1 && sh ~/.config/hypr/shuffle-wallpaper.sh")
end)

hl.on("config.reloaded", function()
	hl.exec_cmd("sleep 1 && sh ~/.config/hypr/shuffle-wallpaper.sh")
	hl.exec_cmd("sh ~/.config/hypr/coretemp.sh")
end)
